document.querySelectorAll('[data-lab="PM08-I1"]').forEach(root=>{const g=k=>root.querySelector('[data-field="'+k+'"]'),zh=root.dataset.lang==='zh';const update=()=>{const h=+g('h').value,j=+g('j').value/1000,d=4*3*50**3*j/(15*h**3),ratio=d/50;g('ho').textContent=h.toFixed(1)+' mm';g('jo').textContent=(j*1000).toFixed(2)+' GPa⁻¹';g('beam').setAttribute('stroke-width',h*8);g('beam').setAttribute('d',Array.from({length:31},(_,i)=>{const r=i/30;return(i?'L':'M')+(80+400*r)+' '+(150+d*8*r*r*(3-r)/2)}).join(' '));const start=150+d*8+h*4,end=start+55;g('force').setAttribute('y1',start);g('force').setAttribute('y2',end);g('arrow').setAttribute('d','M472 '+(end-12)+' L480 '+end+' L488 '+(end-12));const scope=ratio>.05?(zh?' 挠度超过梁长的5%，请把该组合转入大挠度检查；5%为本交互的检查提示。':' Deflection exceeds 5% of span: examine large-deflection effects; 5% is this interaction’s review trigger.'):(zh?' 当前挠度较小；使用线性梁近似，并检查材料应力范围。':' Deflection is relatively small; use the linear beam approximation while checking the material stress range.');g('result').textContent=zh?'端部挠度 '+d.toFixed(3)+' mm，为梁长的 '+(ratio*100).toFixed(2)+'%。柔量是给定状态的输入，未指定通用时间增长律。'+scope:'Tip deflection '+d.toFixed(3)+' mm, '+(ratio*100).toFixed(2)+'% of span. Compliance is an input for a specified state; no universal time-growth law is assumed.'+scope;};root.querySelectorAll('input').forEach(el=>el.addEventListener('input',update));update();});